add_filter( 'wp_img_tag_add_loading_attr', 'perfectpixel_exclude_images_from_lazy_load', 20, 2 );
add_filter( 'jetpack_lazy_images_blocked_classes', 'perfectpixel_exclude_images_from_jetpack_lazy' );

function perfectpixel_no_lazy_keywords() {
	return array_filter( array_map( 'trim', explode( ',', '{{no_lazy_keywords}}' ) ) );
}

function perfectpixel_exclude_images_from_lazy_load( $value, $image ) {
	foreach ( perfectpixel_no_lazy_keywords() as $keyword ) {
		if ( false !== strpos( $image, $keyword ) ) {
			return false;
		}
	}
	return $value;
}

function perfectpixel_exclude_images_from_jetpack_lazy( $classes ) {
	return array_merge( (array) $classes, perfectpixel_no_lazy_keywords() );
}
